import{_ as d,a0 as s,w as a,s as l,ao as p,I as n,x as o,a1 as i,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"安卓编年史 | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/03 - The history of Android","title":"安卓编年史","tag":"The history of Android","desc":""},"relativePath":"The history of Android/03 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/03 - The history of Android.md"};function f(u,t,T,h,g,A){const e=s("Link");return a(),l("div",null,[t[20]||(t[20]=p('<h1 id="安卓编年史" tabindex="-1">安卓编年史 <a class="header-anchor" href="#安卓编年史" aria-label="Permalink to “安卓编年史”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/09hom2e.png" alt="从左到右：安卓0.9的主屏幕，添加的应用抽屉，以及快捷方式删除界面。"></p><p><em>从左到右：安卓0.9的主屏幕，添加的应用抽屉，以及快捷方式删除界面</em> [Ron Amadeo供图]</p><h3 id="android-0-9-beta——嘿-这看起来很眼熟" tabindex="-1">Android 0.9, Beta——嘿，这看起来很眼熟！ <a class="header-anchor" href="#android-0-9-beta——嘿-这看起来很眼熟" aria-label="Permalink to “Android 0.9, Beta——嘿，这看起来很眼熟！”">​</a></h3>',4)),n("p",null,[t[1]||(t[1]=o("Milestone 5发布后六个月，2008年8月， ",-1)),i(e,{href:"http://arstechnica.com/information-technology/2008/08/robotripping-hands-on-with-the-android-sdk-beta/"},{default:r(()=>[...t[0]||(t[0]=[o("安卓0.9发布",-1)])]),_:1}),t[2]||(t[2]=o("。尽管安卓0.5 milestone版看起来“很早期”，而此时距离1.0发布也只有两个月时间了。因此，安卓0.9被打上了“beta”的标签。在移动操作系统之路的另一边，苹果在一个月前已经发布了iPhone的第二代产品——iPhone 3G。第二代的iPhone搭载了第二代iPhone OS。苹果同样发布了App Store应用商店并且已经开始接受应用提交。谷歌在追赶的道路上还有很多事情要做。",-1))]),t[21]||(t[21]=n("p",null,"谷歌抛弃了很多在Milestone 5中引入的UI设计。所有设计都回炉重造，采用全彩设计，白色方形图标背景被抛弃。尽管0.9还是一个模拟器版本，相比与安卓发布版来说看起来还是有点熟悉。安卓0.9有一个可用的桌面式主屏幕，一个特有的应用抽屉，多主屏，更多的应用程序，以及全功能（仅是它自身的）小部件。",-1)),t[22]||(t[22]=n("p",null,"Milestone 5中似乎没有计划支持安装21个以上的应用，但在安卓0.9中有一个垂直滚动的应用抽屉，可以通过屏幕底部的灰色标签打开。那时候，应用抽屉真的只是个抽屉。除了作为一个按钮使用，灰色标签还可以跟随你的手指被向上拉起，就像通知面板被拉下来那样。还额外添加了一些应用，像闹钟，计算器，图片，信息，以及照相机。",-1)),t[23]||(t[23]=n("p",null,"这是第一个可以完全自定义主屏幕的版本。长按应用或小部件可以拖动它们。你可以把应用从抽屉中拖出到主屏幕快捷方式，或长按一个已经存在的主屏幕快捷方式来移动它。",-1)),n("p",null,[t[4]||(t[4]=o("安卓0.9提醒我们谷歌那时候并不像今天这样擅长设计。实际上，当时安卓的部分设计工作外包给了其它公司。你可以从时钟小插件看出一点端倪，它包含了“MALMO”字样，它是设计公司",-1)),i(e,{href:"http://www.tat.se/"},{default:r(()=>[...t[3]||(t[3]=[o("The Astonishing Tribe",-1)])]),_:1}),t[5]||(t[5]=o("的所在地。",-1))]),t[24]||(t[24]=p('<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/widgets.png" alt="安卓0.9的“添加到主屏幕”对话框。"></p><p><em>安卓0.9的“添加到主屏幕”对话框</em> [Ron Amadeo供图]</p><p>安卓0.9中只有三个小部件：时钟，相框和搜索。搜索小部件在列表中甚至没有一个自己的图标——它用的是图片的图标。也许这里面最有趣的选项是壁纸选项中的“购买的图片”——一个“在非智能机时购买铃声是个普遍的现象”的遗留产物。谷歌要么准备出售壁纸，要么在某时已经加入了一个运营商。不过这家公司最终从未实现这个计划。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/fcp.png" alt="小部件集合，打开的文件夹，重命名文件夹，以及一个复制/粘贴菜单。"></p><p><em>小部件集合，打开的文件夹，重命名文件夹，以及一个复制/粘贴菜单</em> [Ron Amadeo供图]</p><p>在上面左侧的截图展示了谷歌搜索和图片小部件。除了给你一个框进行输入之外，搜索小部件做不了其它事情——它没有自动补全或是附加的UI界面。在框里输入并点击“Go”会启动浏览器。底部的一排图标显示了一些菜单中通过长按得到的“快捷方式”，它会创建图标并将应用启动到特定屏幕。独立的联系人，浏览器书签，以及音乐播放列表都是0.9中可以被添加到主屏幕上的快捷方式。</p><p>“文件夹”是快捷方式标题下的一个选项，尽管它并不是任何东西的快捷方式。一旦创建了一个空文件夹，图标就可以被移动进去并重新排列。不像今天，那时候的文件夹里有什么并不反映在文件夹图标上，它一直是一个简单的，白色的，看起来空空的文件夹图标。</p><p>0.9同样是第一个拥有系统级别复制/粘贴支持的安卓版本。长按任意文本框会唤出一个对话框，从而让你保存或撤销剪贴板中的文本。iOS直到近两年后才支持复制/粘贴，所以在一段时间内，这是安卓的特色之一——以及许多网络争议的源头。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/stuff.jpg" alt="从左到右：安卓0.9的新菜单，最近使用应用，电源选项，以及锁屏。"></p><p><em>从左到右：安卓0.9的新菜单，最近使用应用，电源选项，以及锁屏</em> [Ron Amadeo供图]</p><p>安卓0.9真正地开始显示出了它的成熟。主屏幕有完整的菜单选项，包括设置（尽管它还不能正常运作）以及搜索按钮（谷歌肯定很喜欢你去搜索）。从那时起菜单的设计便已经最终成型，直到安卓2.3它转变成了黑色。</p><p>长按实体Home键会唤出一个3x2方格的“最近使用应用”的菜单，这是一个一直持续到安卓3.0的设计。“最近使用应用”菜单会将背景显示模糊化，但这个设计用在这里显得有些奇怪，在其它弹窗比如“添加到主屏幕”对话框或是主屏幕文件夹视图之中并没有用到该设计。电源菜单至少包含在了背景模糊设计组之中，它的图标经过了重新设计，并且功能的对应名称更改得更容易让人接受。不过电源菜单图标缺乏填充，显得有些拥挤和不雅观。</p><p>安卓0.9以其锁屏为特色，虽然是非常基础的样子。黑色和灰色的锁屏没有任何屏幕解锁的选项——你需要点击实体菜单键。</p><hr><p><img src="http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg" alt="Ron Amadeo"></p>',15)),n("p",null,[i(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:r(()=>[...t[6]||(t[6]=[o("Ron Amadeo",-1)])]),_:1}),t[7]||(t[7]=o(" / Ron是Ars Technica的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1))]),n("p",null,[i(e,{href:"https://twitter.com/RonAmadeo"},{default:r(()=>[...t[8]||(t[8]=[o("@RonAmadeo",-1)])]),_:1})]),t[25]||(t[25]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),i(e,{href:"http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/3/"},{default:r(()=>[...t[9]||(t[9]=[o("http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/3/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=o("译者：",-1)),i(e,{href:"https://github.com/alim0x"},{default:r(()=>[...t[11]||(t[11]=[o("alim0x",-1)])]),_:1}),t[14]||(t[14]=o(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[12]||(t[12]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=o("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[15]||(t[15]=[o("LCTT",-1)])]),_:1}),t[18]||(t[18]=o(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:r(()=>[...t[16]||(t[16]=[o("Linux中国",-1)])]),_:1}),t[19]||(t[19]=o(" 荣誉推出",-1))])])}const w=d(m,[["render",f]]);export{b as __pageData,w as default};
